import{_ as n,l as i,o as t,c as s,v as h,p as d,x as o,d as l,i as p,S as m,b as e}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"哈希路由","description":"","frontmatter":{"title":"哈希路由","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hash-routing.md","filePath":"llm/hash-routing.md","lastUpdated":1789023840000}'),c={name:"llm/hash-routing.md"};function u(k,a,E,f,A,B){const r=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=h('<h1 id="哈希路由" tabindex="-1">哈希路由 <a class="header-anchor" href="#哈希路由" aria-label="Permalink to &quot;哈希路由&quot;">​</a></h1><div class="epigraph"><p>用固定哈希把 token 分到专家，路由没有可学习参数，负载由哈希决定，也不再需要辅助损失。</p><footer>—— Roller, Sukhbaatar &amp; Weston, Hash Layers For Large Sparse Models, NeurIPS 2021</footer></div><p><a href="/llm/state-size-vs-context">上一课</a>把序列记忆预算钉死，并声明 MoE 专家数不是状态维。主干 <a href="/llm/moe-routing">MoE 路由</a> 用可学习线性把 token 送到 top-\\(k\\) 专家，再靠均衡损失对抗崩塌。本课从补层「MoE 进阶」起笔：先问能不能<strong>去掉可学习路由</strong>。哈希层用 token 身份或特征的固定哈希选专家。后课 Soft MoE、无辅助损失均衡，都默认你会「可学习门不是唯一分派器」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可学习路由有三笔税：门参数与其不稳定、辅助损失与主损失抢梯度、训练与推理的负载不一致。<a href="/llm/switch-transformer">Switch</a> 把 \\(k\\) 收到 1，税还在。缺口是：若只想要稀疏参数、不在乎「这个专家语义上专精什么」，能否用无参数的哈希保证负载近乎均匀，把优化还给专家本身。</p><p>Roller 等人的 Hash Layers 在大稀疏模型上验证这条。哈希键可以是 token id、位置、或上一层表示的量化——课序默认 token 特征哈希，强调固定性。</p><p><span class="marginnote">哈希路由仍是 token choice：每个 token 独立进桶。它不是 expert choice，生成时也没有未来泄漏问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 token 表示 \\(x\\) 或离散 id，计算 \\(h=\\mathrm{hash}(x)\\bmod N\\)，把 \\(x\\) 送到专家 \\(E_h\\)。可用若干独立哈希取 top-\\(k\\) 个桶，模拟多专家。训练与推理同一哈希，无 dropout 式随机门。容量因子仍可保留：桶过满时溢出到第二哈希，避免极端碰撞。</p><p>没有路由 logits，就没有「把概率乘回输出」的 Switch 变体问题。专家输入是硬分派的 \\(x\\)。若哈希只看 token id，同一词永远进同一专家，词表被静态划分；若看连续表示，须先量化，否则浮点扰动会改变桶——那又引入抖动，后课会写。</p><h3 id="均衡如何得到" tabindex="-1">均衡如何得到 <a class="header-anchor" href="#均衡如何得到" aria-label="Permalink to &quot;均衡如何得到&quot;">​</a></h3><p>理想哈希下各桶期望均等。真实语言模型的 token 分布极不均：高频功能词会打满某些桶，若哈希键是 id。因此实践中更常哈希连续特征或加盐，让高频词仍能散开。均匀是哈希质量问题，不是辅助损失问题。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可学习路由的好处是专家可以按内容聚类（句法专家、代码专家）。哈希放弃聚类，换稳定性与零路由参数。专家仍会在自己看见的数据子集上特化，但特化轴是哈希切开的任意切片，不一定可解释。微调时哈希不变，专家分工被冻在切片上，不能靠改门把一类新任务送到少数专家——这与后课 MoE 微调的可学习门形成对照。</p><p>计算图没有 All-to-All 之前的 softmax 门，但 All-to-All 仍在：token 仍要按桶聚到拥有该专家的设备。<a href="/llm/moe-comm-compute-ratio">通信比</a> 课会算这笔，哈希只省了门，不省通信。多哈希取 \\(k\\) 个桶时，碰撞与均匀改善，但同一 token 仍可能被送进语义无关的一对专家，专家内部的分拣负担随 \\(k\\) 涨。</p><p><span class="marginnote">固定哈希与位置绑定会让「第 \\(i\\) 个位置总进专家 \\(i\\bmod N\\)」，负载均匀但语义灾难。不要用位置当唯一哈希键。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>需要内容特化的任务上，哈希通常弱于可学习 top-\\(k\\)。哈希碰撞把无关 token 塞进同一专家，专家内部还要自己分拣，浪费宽度。不能把哈希层的检查点改回可学习门而不重训。下一课 Soft MoE 走另一极端：每个 token 与每个专家都有软组合，均衡天生，但不再稀疏。</p>',18)),(t(),d(m,null,{default:o(()=>[p(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%20%E6%88%96%E8%A1%A8%E7%A4%BA%22%5D%20--%3E%20H%5B%22%E5%9B%BA%E5%AE%9A%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20B%5B%22%E6%A1%B6%E5%8F%B7%22%5D%0A%20%20B%20--%3E%20E%5B%22%E5%AF%B9%E5%BA%94%E4%B8%93%E5%AE%B6%22%5D%0A%20%20E%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"哈希路由用固定分派换掉可学习门与辅助损失，负载靠哈希质量。"),e("li",null,"专家仍会在切片上特化，但轴不一定语义可解释，微调也不能改门。"),e("li",null,"不省 All-to-All；只省路由参数与其不稳定性。"),e("li",null,"词表 id 哈希会被词频打歪；位置哈希会毁语义。"),e("li",null,"出处：Roller et al., NeurIPS 2021。")],-1))])}const _=n(c,[["render",u]]);export{b as __pageData,_ as default};
